class CompositionRoot {
    PlaceOrderUseCase resolveAdapterForEnvironment(String environment) {
        OrderRepositoryPort repository = environment.equals("production")
            ? new JdbcOrderRepositoryAdapter()   // prawdziwa baza, tylko tutaj wybrana
            : new InMemoryOrderRepositoryAdapter(); // wersja testowa, tylko tutaj wybrana
        return new PlaceOrderService(repository); // Service NIE WIE, ktory adapter dostal
    }
}

