void runRepositoryContractTest(OrderRepositoryPort adapter) {
    adapter.save("order-1");
    if (!adapter.existsById("order-1")) {
        throw new AssertionError("Adapter zlamal kontrakt: zapisany element powinien byc odnajdywalny");
    }
}

