// ZLE: adapter sam liczy regule biznesowa (rabat ilosciowy)
class LeakyPricingAdapter implements PricingPort {
    public double fetchPrice(double basePrice, int quantity) {
        return quantity >= 10 ? basePrice * 0.9 : basePrice; // regula biznesowa W ADAPTERZE!
    }
}

// DOBRZE: adapter tylko pobiera surowe dane, bez logiki biznesowej
class CleanPricingAdapter implements PricingPort {
    public double fetchRawPrice(String productId) {
        return 100.0; // symulacja pobrania surowej ceny z zewnetrznego zrodla
    }
}

// Regula biznesowa zyje W APLIKACJI, nie w adapterze:
double applyBulkDiscountInApplication(double rawPrice, int quantity) {
    return quantity >= 10 ? rawPrice * 0.9 : rawPrice;
}
